 		*(__be32 *)data = cpu_to_be32(IOAM6_U32_UNAVAILABLE);
 		data += sizeof(__be32);
 	}

 	/* namespace data */
 	if (trace->type.bit5) {
 		*(__be32 *)data = ns->data;
 		data += sizeof(__be32);
 	}

 	/* queue depth */
 	if (trace->type.bit6) {
 		struct netdev_queue *queue;
 		struct Qdisc *qdisc;
 		__u32 qlen, backlog;

